# Brute force search for magic sequence of length 3
# x[i] = count of occurrences of i in the sequence

for x0 in range(4):
    for x1 in range(4):
        for x2 in range(4):
            seq = [x0, x1, x2]
            # Check if x[i] == count of i in sequence
            valid = True
            for i in range(3):
                if seq.count(i) != seq[i]:
                    valid = False
                    break
            if valid:
                print(f"Found: {seq}")
